-- Update only the untouched standard demo text. Preserve custom/live settings
-- and the agreed historical terms saved in existing appointment snapshots.
UPDATE "SalonSettings"
SET "bookingTerms" = 'Демонстрационные условия: салон и услуги вымышлены. Запись сохраняется в локальной базе. При требуемой предоплате время временно резервируется; без оплаты бронь автоматически истекает. Доступна только тестовая оплата без списания денег; успешный проверенный тестовый платёж подтверждает запись. Настоящий платёжный провайдер не подключён. Если предоплата не требуется, запись подтверждается сразу. Договор с настоящим салоном не заключается. Перед запуском салон должен подготовить свои условия записи, отмены и переноса.',
    "updatedAt" = CURRENT_TIMESTAMP
WHERE "isDemo" = true
  AND "bookingTerms" = 'Демонстрационные условия: салон и услуги вымышлены. Запись сохраняется в локальной базе. При требуемой предоплате время временно резервируется; без оплаты бронь автоматически истекает. Онлайн-оплата пока не подключена. Если предоплата не требуется, запись подтверждается сразу. Договор с настоящим салоном не заключается. Перед запуском салон должен подготовить свои условия записи, отмены и переноса.';
